#include "World/Modular/RARomanModuleCatalog.h"
static FRARomanGenerationMessage RAMsg(FName C,const FString& M,bool E){FRARomanGenerationMessage R;R.Code=C;R.Message=M;R.bIsError=E;return R;}
bool URARomanModuleCatalog::FindModuleById(FName ModuleId, FRARomanModuleDefinition& OutModule) const { for(const FRARomanModuleDefinition& M:Modules){ if(M.ModuleId==ModuleId){OutModule=M; return true;}} return false; }
TArray<FRARomanModuleDefinition> URARomanModuleCatalog::GetModulesByCategory(ERARomanModuleCategory Category) const { TArray<FRARomanModuleDefinition> R; for(const auto& M:Modules){ if(M.Category==Category) R.Add(M);} return R; }
TArray<FRARomanModuleDefinition> URARomanModuleCatalog::GetModulesByTag(FName Tag) const { TArray<FRARomanModuleDefinition> R; for(const auto& M:Modules){ if(M.Tags.Contains(Tag)) R.Add(M);} return R; }
void URARomanModuleCatalog::ValidateCatalog(TArray<FRARomanGenerationMessage>& W,TArray<FRARomanGenerationMessage>& E) const { TSet<FName> Seen; for(const auto& M:Modules){ if(M.ModuleId.IsNone()) E.Add(RAMsg("MissingModuleId",TEXT("Modulo senza ID."),true)); if(Seen.Contains(M.ModuleId)) E.Add(RAMsg("DuplicateModuleId",FString::Printf(TEXT("ID modulo duplicato: %s"),*M.ModuleId.ToString()),true)); Seen.Add(M.ModuleId); if(M.Dimensions.WidthCm<=0||M.Dimensions.DepthCm<=0||M.Dimensions.HeightCm<=0||M.Dimensions.GridSizeCm<=0) E.Add(RAMsg("InvalidDimensions",*M.ModuleId.ToString(),true)); if(!M.Mesh.IsValid() && M.Mesh.IsNull()) W.Add(RAMsg("MissingSoftMesh",FString::Printf(TEXT("Nessuna mesh assegnata per %s."),*M.ModuleId.ToString()),false)); if(M.EstimatedTriangleCost<0) W.Add(RAMsg("NegativeTriangleCost",*M.ModuleId.ToString(),false)); } }
